import { expect, test, uniqueName } from "../../fixtures";

test("vendors from another tenant are invisible", { tag: "@VEN-07" }, async ({ apiAs }) => {
  // Arrange: a vendor owned by the Globex Procurement tenant
  const globex = await apiAs("otherTenant");
  const created = await globex.post("/api/vendors", {
    data: { name: uniqueName("Globex Vendor"), category: "software", contact_email: "ops@globex-procurement.com" },
  });
  expect(created.status(), await created.text()).toBe(201);
  const vendor = await created.json();

  // Act: the Northwind member requests that vendor by id
  const member = await apiAs("member");
  const res = await member.get(`/api/vendors/${vendor.id}`);

  // Assert
  expect(res.status(), await res.text()).toBe(404);
  expect((await res.json()).error.code, await res.text()).toBe("vendor_not_found");
});
